            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"34\" font-family=\"Arial,sans-serif\" font-weight=\"bold\">KNOWLEDGE CHECK</text><text x=\"550\" y=\"100\" text-anchor=\"middle\" fill=\"#888\" font-size=\"23\" font-family=\"Arial,sans-serif\">The quicksand rule</text><rect x=\"100\" y=\"150\" width=\"900\" height=\"316\" rx=\"20\" fill=\"rgba(245,158,11,0.15)\" stroke=\"#f59e0b\" stroke-width=\"2\"/><text x=\"550\" y=\"246\" text-anchor=\"middle\" fill=\"#f59e0b\" font-size=\"28\" font-family=\"Arial,sans-serif\" font-weight=\"bold\">STRUGGLE = SINK</text><text x=\"550\" y=\"322\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"26\" font-family=\"Arial,sans-serif\">Arguing, suppressing, and reassuring all feed the loop</text><text x=\"550\" y=\"390\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"26\" font-family=\"Arial,sans-serif\">Changing your relationship to the thought is the exit</text></svg>",
            "caption": "Mid-lesson check"
