" font-size=\"29\" font-family=\"Arial,sans-serif\" font-weight=\"bold\">4.</text><text x=\"200\" y=\"710\" text-anchor=\"start\" fill=\"#fff\" font-size=\"24\" font-family=\"Arial,sans-serif\">Note which dead end you were using</text><rect x=\"100\" y=\"794\" width=\"900\" height=\"128\" rx=\"20\" fill=\"rgba(59,130,246,0.15)\" stroke=\"#3b82f6\" stroke-width=\"2\"/><text x=\"140\" y=\"871\" text-anchor=\"start\" fill=\"#3b82f6\" font-size=\"29\" font-family=\"Arial,sans-serif\" font-weight=\"bold\">5.</text><text x=\"200\" y=\"871\" text-anchor=\"start\" fill=\"#fff\" font-size=\"24\" font-family=\"Arial,sans-serif\">Record trigger, time, and dead end in one line</text></svg>",
