            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"36\" font-family=\"Arial,sans-serif\" font-weight=\"bold\">VALUE AND ACCESS</text><text x=\"550\" y=\"100\" text-anchor=\"middle\" fill=\"#888\" font-size=\"23\" font-family=\"Arial,sans-serif\">A line readers often quote</text><rect x=\"100\" y=\"190\" width=\"900\" height=\"316\" rx=\"20\" fill=\"rgba(139,92,246,0.15)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/><text x=\"550\" y=\"266\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"28\" font-family=\"Arial,sans-serif\" font-style=\"italic\">\"Some people only understand your value once they</text><text x=\"550\" y=\"354\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"28\" font-family=\"Arial,sans-serif\" font-style=\"italic\">no longer have access to it.\"</text><text x=\"950\" y=\"462\" text-anchor=\"end\" fill=\"#8b5cf6\" font-size=\"22\">— Daniel Chidiac</text><rect x=\"100\" y=\"536\" width=\"900\" height=\"82\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"582\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"23\" font-family=\"Arial,sans-serif\">Their late understanding is not your victory to wait for</text></svg>",
