" font-size=\"26\" font-family=\"Arial,sans-serif\">MANUFACTURED</text><rect x=\"100\" y=\"856\" width=\"900\" height=\"154\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"140\" y=\"948\" text-anchor=\"start\" fill=\"#ffd700\" font-size=\"30\" font-family=\"Arial,sans-serif\" font-weight=\"bold\">4.</text><text x=\"200\" y=\"948\" text-anchor=\"start\" fill=\"#fff\" font-size=\"26\" font-family=\"Arial,sans-serif\">One repair, two releases</text></svg>",
